document.addEventListener('touchmove',e=>{if(!gesture)return;const t=point(e.touches,gesture.id);if(!t||e.touches.length!==1){clearDrag();return}const dx=t.clientX-gesture.x,dy=t.clientY-gesture.y;if(!gesture.tracking){if(Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)*.7){clearDrag();return}if(Math.abs(dx)<12||Math.abs(dx)<Math.abs(dy)*1.4)return;const side=gesture.open||(dx>0?'sessions':'files');if(gesture.open==='sessions'&&dx>0||gesture.open==='files'&&dx<0||!gesture.open&&(dx>0?gesture.blockRight:gesture.blockLeft)){gesture=null;return}if(side==='files'&&!current){gesture=null;return}gesture.side=side;gesture.width=panelOf(side).getBoundingClientRect().width;gesture.tracking=true;document.body.classList.add('dragging');if(side==='files'&&!gesture.open&&!filesPath)void showFiles('')}e.preventDefault();const sign=gesture.side==='files'?-1:1,progress=Math.max(0,Math.min(1,((gesture.open?gesture.width:0)+sign*dx)/gesture.width));panelOf(gesture.side).style.transform='translateX('+(sign*(progress-1)*100)+'%)';$('shade').style.opacity=String(progress);$('shade').style.pointerEvents=progress>0?'auto':'none'},{passive:false});
